    /**
     * Whether the plan lets the customer spend past the allowance it grants on a
     * dimension. Overage has to be asked for explicitly, so anything other than
     * an affirmative answer keeps the customer inside their allowance.
     */
    static overageIsPermitted(overageAllowed?: overageAllowedEnum | boolean | string): boolean {
        return overageAllowed !== undefined && overageAllowed !== null && String(overageAllowed) === 'true';
    }

    /**
     * The part of a dimension's usage the customer actually owes for.
     *
     * An allowance covers usage up to its own size, so only what spills past a
     * finite allowance can be owed, and then only when the plan permits overage.
     * An unlimited allowance covers everything and a dimension with no allowance
     * at all is owed for in full.
     */
    static billableQuantity({
        total,
        usageEntitlement,
        overageAllowed,
    }: {
        total: number | string;
        usageEntitlement?: number | 'inf';
        overageAllowed?: overageAllowedEnum;
    }): number {
        const usage = parseFloat(`${total ?? 0}`) || 0;
        if (usageEntitlement === undefined || usageEntitlement === null) {
            // Nothing is granted, so everything measured is owed for.
            return usage;
        }
        if (usageEntitlement === 'inf') {
            // An unlimited allowance can never be exhausted.
            return 0;
        }
        const allowance = parseFloat(`${usageEntitlement}`);
        if (Number.isNaN(allowance)) {
            return usage;
        }
        if (!Offering.overageIsPermitted(overageAllowed)) {
            // The plan holds the customer to their allowance.
            return 0;
        }
        const overage = usage - allowance;
        return overage > 0 ? Number(overage.toFixed(2)) : 0;
    }

    /**
     * Whether a dimension the plan prices at zero should be kept off the invoice,
     * which is a choice the business makes in its invoice settings.
     */
    static freeDimensionsAreHidden(settings?: ReadSettingsResponseData): boolean {
        return settings?.freeDimensionOnInvoice === FreeDimensionOnInvoice.hide;
    }

    /**
     * A dimension earns a line when the customer owes something on it. A
     * dimension priced at zero owes nothing but is still reported, unless the
     * invoice settings ask for free dimensions to be left off.
