    static dimensionEarnsLine({
        quantity,
        unitCost,
        settings,
    }: {
        quantity: number;
        unitCost: number;
        settings?: ReadSettingsResponseData;
    }): boolean {
        if (!unitCost) {
            return !Offering.freeDimensionsAreHidden(settings);
        }
        return Math.abs(quantity) > 0;
    }
