import { ValidBillingCycles, OfferingVisibility } from './offering/dto/createOffering.dto.js';

const dim = (overrides) => ({
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    rounding: roundingEnum.round,
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    usageIncrement: '1',
    ...overrides,
});

const run = async (dimensions, usage, freeDimensionOnInvoice = FreeDimensionOnInvoice.show) => {
    const offeringConfig = {
        offeringId: 'off',
        offeringName: 'Plan',
        offeringType: OfferingType.usageBased,
        billingCycle: ValidBillingCycles.monthly,
        offeringVisibility: OfferingVisibility.public,
        dimensions,
    } as any;
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: new Date('2026-07-01T00:00:00Z'),
        endDate: new Date('2026-08-01T00:00:00Z'),
        lineItems,
        negative: false,
        businessID: 'biz',
        customerId: 'cus',
        customerService: undefined,
        dimensions,
        offeringInstance: Offering.getInstance(
            offeringConfig,
            'cus',
            'biz',
            undefined,
            { freeDimensionOnInvoice } as ReadSettingsResponseData,
            undefined,
            undefined,
            undefined,
            usage,
        ),
    });
    return lineItems.getLineItems();
};

const usageFor = (dimensionId, value) => ({
    offeringId: 'off',
    dimensionId,
    usage: [{ value: `${value}`, startTime: '2026-07-02T00:00:00Z', endTime: '2026-07-02T00:00:00Z' }],
});

describe('entitlement + free dimension edges', () => {
    test('no entitlement charges everything', async () => {
        expect(await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2' })], [usageFor('d', 30)])).toEqual([
            expect.objectContaining({ name: 'D - Plan', quantity: 30, unitCost: 2 }),
        ]);
    });
    test('exhausted finite allowance with overage charges only the overage', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true })], [usageFor('d', 30)]),
        ).toEqual([expect.objectContaining({ name: 'D - Plan', quantity: 20, unitCost: 2 })]);
    });
    test('unexhausted allowance charges nothing and gets no line', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 40, overageAllowed: overageAllowedEnum.true })], [usageFor('d', 30)]),
        ).toEqual([]);
    });
    test('allowance exactly consumed charges nothing', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 30, overageAllowed: overageAllowedEnum.true })], [usageFor('d', 30)]),
        ).toEqual([]);
    });
    test('unlimited allowance charges nothing', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 'inf', overageAllowed: overageAllowedEnum.true })], [usageFor('d', 30)]),
        ).toEqual([]);
    });
    test('forbidden overage charges nothing', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.false })], [usageFor('d', 30)]),
        ).toEqual([]);
    });
    test('missing overage answer charges nothing', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '2', usageEntitlement: 10 })], [usageFor('d', 30)]),
        ).toEqual([]);
    });
    test('entitlement with no price shows a zero line when free dimensions are shown', async () => {
        expect(await run([dim({ dimensionId: 'd', dimensionName: 'D', usageEntitlement: 10 })], [usageFor('d', 30)])).toEqual([
            expect.objectContaining({ name: 'D - Plan', quantity: 0, unitCost: 0 }),
        ]);
    });
    test('zero priced dimension reports the owed quantity when shown', async () => {
