            expect.objectContaining({ name: 'D - Plan', quantity: 30, unitCost: 0 }),
        ]);
    });
    test('zero priced dimension is hidden when settings hide free dimensions', async () => {
        expect(
            await run([dim({ dimensionId: 'd', dimensionName: 'D', consumptionPrice: '0.00' })], [usageFor('d', 30)], FreeDimensionOnInvoice.hide),
